{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
<header class="site-header">
  <div class="container">
    <a class="brand" href="index.html"><img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" class="logo"> <span class="brand-text">{{BUSINESS_NAME}}</span></a>
    <nav class="nav">
      <ul>
        <li><a href="index.html">Home</a></li>
        <li><a href="about.html">About</a></li>
        <li><a href="programs.html">Paths</a></li>
        <li><a href="pricing.html">Pricing</a></li>
        <li><a href="testimonials.html">Stories</a></li>
        <li><a href="book.html">{{PRIMARY_CTA_LABEL}}</a></li>
        <li><a href="contact.html">Contact</a></li>
      </ul>
      <button class="nav-toggle" aria-label="Toggle menu">☰</button>
    </nav>
  </div>
</header>

<main>
  <section id="hero" class="hero">
    <div class="container hero-grid">
      <div class="hero-copy">
        <p class="eyebrow">Transform daily habits into lasting well-being</p>
        <h1>{{TAGLINE}}</h1>
        <p class="lede">Work with {{COACH_NAME}}, {{CREDENTIALS}}, to build simple routines, measurable habits, and a life that feels balanced in {{CITY}}, {{STATE}}.</p>
        <div class="hero-ctas">
          <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn btn-outline" href="book.html">Schedule a free consult</a>
        </div>
        <form id="leadForm" class="lead-form" aria-label="Download guide">
          <label for="leadEmail">Grab a free guide: 7 daily habits</label>
          <input id="leadEmail" name="email" type="email" placeholder="your@email.com" required>
          <button class="btn" type="submit">Get the guide</button>
        </form>
      </div>
      <div class="hero-visual">
        <img src="assets/img/hero.svg" alt="Illustration" />
      </div>
    </div>
  </section>

  <section id="story" class="story container">
    <div class="story-inner">
      <img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" class="story-avatar">
      <h2>Why I coach: a simple story</h2>
      <p>I started as a busy professional craving small, dependable changes. I studied behaviour design and turned those habits into a framework I now share with clients. My approach blends practical tracking, compassionate accountability, and progressive goal-setting.</p>
      <p class="muted">No fads. No quick fixes. Just steady work that compounds.</p>
    </div>
  </section>

  <section id="framework" class="framework">
    <div class="container">
      <h2>Core framework: The 3C Method</h2>
      <p class="intro">A structured path to sustainable change — Clear, Contextual, Consistent.</p>
      <div class="grid">
        <div class="card">
          <h3>Clear</h3>
          <p>Define outcomes first. We map measurable mini-goals that fit your life.</p>
        </div>
        <div class="card">
          <h3>Contextual</h3>
          <p>Design cues and routines that match your day-to-day environment.</p>
        </div>
        <div class="card">
          <h3>Consistent</h3>
          <p>Small, repeatable actions tracked weekly to create momentum.</p>
        </div>
      </div>
    </div>
  </section>

  <section id="programs" class="programs container">
    <h2>Programs (paths) — choose how we work together</h2>
    <div class="grid programs-grid">
      <div class="program">
        <h3>Starter Path</h3>
        <p>8-week habit foundations, weekly check-ins, habit tracker template.</p>
        <a href="programs.html#starter" class="btn btn-sm">Explore</a>
      </div>
      <div class="program">
        <h3>Momentum Cycle</h3>
        <p>12-week momentum plan with coaching and accountability calls.</p>
        <a href="programs.html#momentum" class="btn btn-sm">Explore</a>
      </div>
      <div class="program">
        <h3>Transformation Arc</h3>
        <p>6-month deep work package for layered habit and lifestyle shifts.</p>
        <a href="programs.html#transformation" class="btn btn-sm">Explore</a>
      </div>
    </div>
  </section>

  <section id="pricing" class="pricing container">
    <h2>Flexible pricing & commitments</h2>
    <p class="intro">Choose time-bound coaching or a membership model.</p>
    <div class="grid pricing-grid">
      <div class="tier">
        <h3>Monthly Membership</h3>
        <p class="price">From $79/mo</p>
        <ul>
          <li>Weekly group sessions</li>
          <li>Monthly 1:1 (15-min)</li>
          <li>Resource library</li>
        </ul>
        <a href="pricing.html#membership" class="btn">Join</a>
      </div>
      <div class="tier">
        <h3>Short Course</h3>
        <p class="price">$499 one-time</p>
        <ul>
          <li>8-week guided course</li>
          <li>Templates + tracker</li>
          <li>Email support</li>
        </ul>
        <a href="pricing.html#course" class="btn">Buy</a>
      </div>
      <div class="tier">
        <h3>Dedicated Coaching</h3>
        <p class="price">$1200/3mo</p>
        <ul>
          <li>Bi-weekly 1:1 coaching</li>
          <li>Customized plan</li>
          <li>Direct messaging</li>
        </ul>
        <a href="pricing.html#dedicated" class="btn">Apply</a>
      </div>
    </div>
  </section>

  <section id="testimonials" class="testimonials container">
    <h2>What clients say</h2>
    <div class="grid testimonials-grid">
      <blockquote class="quote">
        <p>"Working with {{COACH_NAME}} changed how I think about daily progress. The small wins added up fast."</p>
        <footer>— A client in {{CITY}}</footer>
      </blockquote>
      <blockquote class="quote">
        <p>"Clear structure, compassionate coaching, and real accountability. I feel steady for the first time in years."</p>
        <footer>— A member in {{STATE}}</footer>
      </blockquote>
    </div>
  </section>

  <section id="cta" class="cta">
    <div class="container cta-inner">
      <h2>Ready to make habits stick?</h2>
      <p>Start with a short conversation. We'll map one practical change you can begin this week.</p>
      <a class="btn btn-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </section>
</main>

<footer class="site-footer">
  <div class="container">
    <div class="footer-grid">
      <div>
        <p class="brand-small">{{BUSINESS_NAME}} — {{CREDENTIALS}}</p>
        <p class="muted">Serving {{CITY}}, {{STATE}}</p>
      </div>
      <div>
        <p>Contact</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
    <p class="small muted">© <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved.</p>
  </div>
</footer>

<script src="assets/js/main.js"></script>
</body>
</html>"} 
