{"path":"assets/css/styles.css","content":":root{
  --bg:#0b0b0b;
  --paper:#ffffff;
  --muted:#9aa0a6;
  --accent:#ff6b6b;
  --accent-2:#ffd166;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--paper);line-height:1.5;margin:0}
.container{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{border-bottom:1px solid rgba(255,255,255,0.06);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
.site-header .container{display:flex;align-items:center;justify-content:space-between;padding:1rem 2rem}
.brand{display:flex;align-items:center;gap:.75rem;text-decoration:none;color:var(--paper)}
.logo{width:48px;height:48px}
.brand-text{font-weight:700;letter-spacing:.4px}
.nav ul{display:flex;gap:1rem;list-style:none;margin:0;padding:0}
.nav a{color:var(--paper);text-decoration:none;padding:.25rem .4rem;font-weight:600}
.nav-toggle{display:none;background:transparent;border:0;color:var(--paper);font-size:1.2rem}

/* Hero */
.hero{padding:3.5rem 0;background:linear-gradient(135deg,rgba(255,255,255,0.02),rgba(0,0,0,0));border-bottom:1px solid rgba(255,255,255,0.03)}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:2rem;align-items:center}
.eyebrow{color:var(--accent-2);text-transform:uppercase;font-weight:700;letter-spacing:1px;margin:0 0 .5rem}
.hero h1{font-size:2.25rem;margin:.1rem 0 .6rem;line-height:1.05;color:var(--paper)}
.lede{color:var(--muted);max-width:46ch}
.hero-ctas{display:flex;gap:.8rem;margin:1rem 0}
.btn{background:transparent;border:1px solid rgba(255,255,255,0.08);color:var(--paper);padding:.6rem .9rem;border-radius:8px;text-decoration:none;cursor:pointer}
.btn-primary{background:var(--paper);color:var(--bg);border:0}
.btn-outline{background:transparent;border:1px solid rgba(255,255,255,0.12)}
.btn-cta{background:var(--accent);border:0;color:#111;padding:.9rem 1.1rem}
.btn-sm{padding:.4rem .6rem;font-size:.9rem}
.lead-form{display:flex;gap:.5rem;align-items:center;margin-top:1rem}
.lead-form input{padding:.6rem .8rem;border-radius:8px;border:1px solid rgba(255,255,255,0.06);background:rgba(255,255,255,0.02);color:var(--paper)}

.hero-visual img{width:100%;height:auto;display:block;border-radius:12px}

/* Story */
.story{padding:3rem 0}
.story-inner{display:flex;gap:1rem;align-items:center}
.story-avatar{width:96px;height:96px;border-radius:12px}
.story h2{margin:0 0 .5rem;color:var(--paper)}
.muted{color:var(--muted)}

/* Framework */
.framework{padding:3rem 0;border-top:1px solid rgba(255,255,255,0.03)}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:1.2rem;border-radius:12px}
.card h3{margin:0 0 .5rem}

/* Programs */
.programs{padding:3rem 0}
.programs-grid .program{background:rgba(255,255,255,0.02);padding:1rem;border-radius:10px}

/* Pricing */
.pricing-grid .tier{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:1rem;border-radius:10px}
.price{font-weight:800;color:var(--accent-2)}

/* Testimonials */
.testimonials{padding:3rem 0}
.testimonials-grid{grid-template-columns:1fr 1fr}
.quote{background:rgba(255,255,255,0.02);padding:1rem;border-radius:8px}

/* CTA */
.cta{padding:3rem 0;background:linear-gradient(90deg,rgba(255,107,107,0.06),rgba(255,209,102,0.03));border-top:1px solid rgba(255,255,255,0.02)}
.cta-inner{text-align:center}

/* Footer */
.site-footer{border-top:1px solid rgba(255,255,255,0.04);padding:2rem 0;margin-top:2rem}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.small{font-size:.85rem}

/* Responsive */
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .grid{grid-template-columns:1fr;}
  .nav ul{display:none}
  .nav-toggle{display:block}
  .site-header .container{padding:1rem}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Nav toggle for small screens
  var toggle=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.nav ul');
  if(toggle){
    toggle.addEventListener('click',function(){
      if(nav.style.display==='flex'){nav.style.display='none'}else{nav.style.display='flex';nav.style.flexDirection='column'}
    });
  }

  // Lead form - mock submission
  var leadForm=document.getElementById('leadForm');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email=leadForm.querySelector('input[name="email"]').value;
      if(!email) return;
      // Simulate success
      var btn=leadForm.querySelector('button');
      btn.disabled=true;btn.textContent='Sending...';
      setTimeout(function(){
        btn.textContent='Sent';
        leadForm.querySelector('input[name="email"]').value='';
        btn.disabled=false;
        // small toast
        var t=document.createElement('div');
        t.className='toast';
        t.textContent='Guide sent to ' + email + ' — check your inbox.';
        Object.assign(t.style,{position:'fixed',right:'16px',bottom:'16px',background:'#111',color:'#fff',padding:'10px 14px',borderRadius:'10px',boxShadow:'0 6px 18px rgba(0,0,0,0.4)'});
        document.body.appendChild(t);
        setTimeout(function(){document.body.removeChild(t)},4000);
      },900);
    });
  }

  // Year update
  var y=document.getElementById('year');
  if(y) y.textContent=new Date().getFullYear();

  // Smooth anchor links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id=this.getAttribute('href').slice(1);
      var target=document.getElementById(id);
      if(target) target.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });
});"} 
